From 601c3d4baffbedca20e0414f73b01d0172922a70 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 01:48:35 +0100
Subject: [PATCH] libs/networkstatus: update the status text when a VPN state
 changes

The tooltip text read the VPN state but was only refreshed on active
connection state changes, so a VPN that finished connecting after that
kept saying "Connecting to". Also listen to the VPN state changes.

BUG: 521254
---
 libs/networkstatus.cpp | 5 ++++-
 1 file changed, 4 insertions(+), 1 deletion(-)

diff --git a/libs/networkstatus.cpp b/libs/networkstatus.cpp
index b778eedda..6bdd1893c 100644
--- a/libs/networkstatus.cpp
+++ b/libs/networkstatus.cpp
@@ -107,7 +107,10 @@ void NetworkStatus::activeConnectionsChanged()
     for (const NetworkManager::ActiveConnection::Ptr &active : NetworkManager::activeConnections()) {
         connect(active.data(), &NetworkManager::ActiveConnection::default4Changed, this, &NetworkStatus::defaultChanged, Qt::UniqueConnection);
         connect(active.data(), &NetworkManager::ActiveConnection::default6Changed, this, &NetworkStatus::defaultChanged, Qt::UniqueConnection);
-        connect(active.data(), &NetworkManager::ActiveConnection::stateChanged, this, &NetworkStatus::changeActiveConnections);
+        connect(active.data(), &NetworkManager::ActiveConnection::stateChanged, this, &NetworkStatus::changeActiveConnections, Qt::UniqueConnection);
+        if (const auto vpnConnection = active.objectCast<NetworkManager::VpnConnection>()) {
+            connect(vpnConnection.data(), &NetworkManager::VpnConnection::stateChanged, this, &NetworkStatus::changeActiveConnections, Qt::UniqueConnection);
+        }
     }

     changeActiveConnections();
-- 
